insert into public.exercises (id, name, aliases, category, movement_pattern, mechanic, force, level, instructions, images, is_common, is_active, source) values
  ('Band_Lat_Pulldown', 'Band Lat Pulldown', array['Resistance Band Pulldown']::text[], 'strength', 'vertical_pull', 'compound', 'pull', 'beginner', array['Anchor a band high (over a pull-up bar or door anchor), kneel or sit facing it, and grip the band with straight arms.', 'Pull your elbows down toward your ribs, driving your chest up to meet the band.', 'Pause, then let your arms rise slowly under control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Row', 'Band Row', array['Resistance Band Row', 'Seated Band Row']::text[], 'strength', 'horizontal_pull', 'compound', 'pull', 'beginner', array['Anchor a band at chest height, hold the ends, and step back until there is tension with arms straight.', 'Pull your hands to your ribs, squeezing your shoulder blades together.', 'Pause, then return with control without letting your shoulders roll forward.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Negative_Pull-Up', 'Negative Pull-Up', array['Eccentric Pull-Up', 'Slow Negative Pull-Up']::text[], 'strength', 'vertical_pull', 'compound', 'pull', 'intermediate', array['Step or jump up so your chin is over the bar with an overhand grip.', 'Lower yourself as slowly as you can, aiming for 3 to 5 seconds, until your arms are fully straight.', 'Step back up and repeat. This builds the strength to do full pull-ups.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Neutral-Grip_Pull-Up', 'Neutral-Grip Pull-Up', array['Hammer Grip Pull-Up', 'Parallel Grip Pull-Up']::text[], 'strength', 'vertical_pull', 'compound', 'pull', 'intermediate', array['Hang from parallel handles with your palms facing each other and arms fully straight.', 'Pull your elbows down and in until your chin clears the handles.', 'Lower under control to a full hang. This grip is easier on the shoulders and wrists.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Pendlay_Row', 'Pendlay Row', array['Dead-Stop Barbell Row']::text[], 'strength', 'horizontal_pull', 'compound', 'pull', 'intermediate', array['Stand over a barbell with feet hip-width, hinge until your back is parallel to the floor, and grip just outside your knees.', 'Explosively row the bar to your lower chest while keeping your back flat and torso still.', 'Lower the bar back to the floor and reset fully before every rep.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Weighted_Chin-Up', 'Weighted Chin-Up', array['Weighted Chinup', 'Belted Chin-Up']::text[], 'strength', 'vertical_pull', 'compound', 'pull', 'intermediate', array['Attach weight with a dip belt, a vest, or a dumbbell between your feet, then hang from the bar with an underhand grip.', 'Pull until your chin clears the bar, leading with your chest and keeping your body steady.', 'Lower to a full hang under control before the next rep.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Bicep_Curl', 'Band Bicep Curl', array['Resistance Band Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Stand on the middle of a band and hold the ends with palms facing forward.', 'Curl your hands toward your shoulders, keeping your elbows pinned to your sides.', 'Lower slowly. The band gets harder toward the top, so squeeze there.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Barbell_21s', 'Barbell 21s', array['21s Curl', 'Twenty-One Curls']::text[], 'strength', 'isolation', 'isolation', 'pull', 'intermediate', array['Hold a barbell with an underhand grip and do 7 reps from the bottom to halfway up.', 'Without resting, do 7 reps from halfway up to the top.', 'Finish with 7 full-range reps. Use a light weight; this one burns.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Bayesian_Cable_Curl', 'Bayesian Cable Curl', array['Bayesian Curl', 'Behind-the-Body Cable Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'intermediate', array['Set a cable low, face away from the stack, and hold the handle behind you with your arm straight and slightly back.', 'Curl the handle up toward your shoulder without letting your elbow swing forward.', 'Lower slowly until the biceps is fully stretched behind your body. Repeat, then switch arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Tibialis_Raise', 'Tibialis Raise', array['Tib Raise', 'Toe Raise', 'Tibialis Anterior Raise']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Lean your back against a wall with your feet about a foot and a half in front, hip-width apart.', 'Keeping your legs straight, pull your toes up toward your shins as high as you can.', 'Lower slowly and repeat. This builds the muscle on the front of your shin and helps protect your knees and ankles.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Hiking', 'Hiking', array['Trail Hike', 'Hike']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Wear sturdy shoes and carry water. Pick a trail with hills for more challenge.', 'Walk at a steady pace, taking shorter steps uphill and keeping your knees soft downhill.', 'Log your distance and time so you can track your progress.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Sprints', 'Sprints', array['Sprint', 'Sprint Intervals', 'Running Sprints']::text[], 'cardio', 'cardio', null, null, 'intermediate', array['Warm up with 5 to 10 minutes of easy jogging and a few short build-up runs.', 'Run at near maximum effort for 10 to 30 seconds, driving your arms and knees.', 'Walk or jog until you fully recover, then repeat for several rounds.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Swimming', 'Swimming', array['Swim', 'Lap Swimming', 'Swim Laps']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Choose a stroke you can keep up, such as freestyle or breaststroke.', 'Swim steadily, breathing in a rhythm, and rest at the wall when needed.', 'Log your laps or time. Mix in intervals to build fitness faster.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Archer_Push-Up', 'Archer Push-Up', array['Archer Pushup']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'expert', array['Start in a wide push-up position with your hands well outside your shoulders.', 'Lower toward one hand while the other arm stays straight out to the side.', 'Press back up, then lower toward the other side. Alternate sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Knee_Push-Up', 'Knee Push-Up', array['Kneeling Push-Up', 'Modified Push-Up', 'Girl Push-Up']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'beginner', array['Get in a push-up position with your knees on the floor and a straight line from knees to head.', 'Lower your chest to just above the floor, elbows at about 45 degrees from your body.', 'Press back up to straight arms. Progress to full push-ups when this feels easy.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Weighted_Dip', 'Weighted Dip', array['Weighted Chest Dip', 'Belted Dip']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'intermediate', array['Attach weight with a dip belt, a vest, or a dumbbell between your feet, then support yourself on the bars with straight arms.', 'Lean slightly forward and lower until your upper arms are about parallel to the floor.', 'Press back up to straight arms without swinging.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Weighted_Push-Up', 'Weighted Push-Up', array['Weighted Pushup', 'Plate Push-Up', 'Vest Push-Up']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'intermediate', array['Put on a weight vest, or have a partner rest a plate on your upper back, and take a push-up position.', 'Lower your chest to just above the floor, keeping your body in a straight line.', 'Press back up to straight arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Barbell_Thruster', 'Barbell Thruster', array['Thruster', 'Barbell Squat to Press']::text[], 'strength', 'other', 'compound', 'push', 'intermediate', array['Hold a barbell in the front rack position on your shoulders and stand with feet shoulder-width apart.', 'Squat down until your thighs are at least parallel to the floor.', 'Drive up out of the squat and use that momentum to press the bar overhead, then lower it back to your shoulders.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Burpee', 'Burpee', array['Burpees']::text[], 'strength', 'other', 'compound', 'push', 'beginner', array['From standing, drop your hands to the floor and jump your feet back into a plank.', 'Lower your chest to the floor, press up, and jump your feet back toward your hands.', 'Explode up into a jump with your arms overhead, then go straight into the next rep.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Clean_and_Press', 'Dumbbell Clean and Press', array['DB Clean and Press', 'Dumbbell Clean & Press']::text[], 'strength', 'hinge', 'compound', 'push', 'intermediate', array['Hold dumbbells at your sides, hinge slightly, then drive your hips forward and pull the weights up to your shoulders.', 'Catch them at shoulder height with a slight dip of your knees.', 'Press both overhead until your arms lock out, then lower to your shoulders and down to your sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Snatch', 'Dumbbell Snatch', array['DB Snatch', 'Single-Arm Dumbbell Snatch']::text[], 'strength', 'hinge', 'compound', 'pull', 'intermediate', array['Hold a dumbbell between your feet, hinge at the hips, and keep your back flat.', 'Drive your hips forward and pull the dumbbell up in one fast motion, punching it overhead.', 'Lock out overhead, then lower it under control back to the start. Switch arms after your reps.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Thruster', 'Dumbbell Thruster', array['DB Thruster']::text[], 'strength', 'other', 'compound', 'push', 'beginner', array['Hold dumbbells at your shoulders and stand with feet shoulder-width apart.', 'Squat down until your thighs are at least parallel to the floor.', 'Stand up forcefully and press the dumbbells overhead in one motion, then lower them back to your shoulders.']::text[], '{}'::text[], true, true, 'catalog'),
  ('High_Knees', 'High Knees', array['High Knee Run', 'Running in Place']::text[], 'strength', 'other', null, null, 'beginner', array['Stand tall and start running in place.', 'Drive each knee up to about hip height while pumping your arms.', 'Stay on the balls of your feet and keep a quick, light rhythm.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Jumping_Jacks', 'Jumping Jacks', array['Jumping Jack', 'Star Jumps']::text[], 'strength', 'other', null, null, 'beginner', array['Stand with feet together and arms at your sides.', 'Jump your feet out wide while swinging your arms overhead.', 'Jump back to the start and repeat at a steady rhythm.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Wall_Ball', 'Wall Ball', array['Wall Ball Shot', 'Medicine Ball Wall Shot']::text[], 'strength', 'other', 'compound', 'push', 'beginner', array['Face a wall about an arm''s length away and hold a medicine ball at your chest.', 'Squat down until your thighs are parallel to the floor.', 'Stand up explosively and throw the ball at a target high on the wall, catch it, and go straight into the next squat.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Bear_Crawl', 'Bear Crawl', array['Bear Walk', 'Crawling']::text[], 'strength', 'core', 'compound', 'pull', 'beginner', array['Start on your hands and feet with your knees hovering just off the floor and your back flat.', 'Move opposite hand and foot forward together, keeping your hips low and level.', 'Crawl a set distance, or go backward, keeping your core tight.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dragon_Flag', 'Dragon Flag', array['Bruce Lee Dragon Flag']::text[], 'strength', 'core', 'compound', 'pull', 'expert', array['Lie on a bench and grip it behind your head, with your shoulders pressed into the pad.', 'Lift your whole body into a straight line, resting only on your upper back.', 'Lower yourself slowly, keeping your body rigid, and stop just above the bench. Bend your knees to make it easier.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Woodchop', 'Dumbbell Woodchop', array['DB Woodchop', 'Medicine Ball Woodchop', 'Standing Woodchop']::text[], 'strength', 'core', 'compound', 'pull', 'beginner', array['Stand with feet wider than your hips and hold a dumbbell with both hands by one hip.', 'Rotate your torso and pivot your back foot as you swing the weight diagonally up and across your body.', 'Control it back down and repeat all your reps, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('GHD_Sit-Up', 'GHD Sit-Up', array['Glute Ham Developer Sit-Up', 'GHD Situp']::text[], 'strength', 'core', 'compound', 'pull', 'expert', array['Set up in a GHD with your feet secured and your hips at the edge of the pad.', 'Lower back until your torso is about level with the floor, keeping your core braced.', 'Sit up until your torso is upright. Start with a small range if you are new to this.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Hanging_Knee_Raise', 'Hanging Knee Raise', array['Hanging Knee Raises', 'Knee Raise']::text[], 'strength', 'core', 'isolation', 'pull', 'beginner', array['Hang from a pull-up bar with arms straight and shoulders engaged.', 'Raise your knees up toward your chest by curling your pelvis toward your ribs.', 'Lower slowly without swinging.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Hollow_Body_Hold', 'Hollow Body Hold', array['Hollow Hold', 'Hollow Rock Hold']::text[], 'strength', 'core', 'isolation', 'static', 'beginner', array['Lie on your back with arms overhead and legs straight.', 'Press your lower back into the floor and lift your shoulders and legs a few inches off it.', 'Hold the shape without letting your lower back arch. Bend your knees to make it easier.']::text[], '{}'::text[], true, true, 'catalog'),
  ('L-Sit', 'L-Sit', array['L Sit', 'Parallel Bar L-Sit']::text[], 'strength', 'core', 'compound', 'static', 'expert', array['Support yourself on parallel bars, rings, or a pull-up bar with straight arms and shoulders pushed down.', 'Lift your legs straight out in front of you until they are parallel to the floor.', 'Hold as long as you can with your legs and arms locked straight. Tuck your knees to make it easier.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Plank_Shoulder_Taps', 'Plank Shoulder Taps', array['Plank Taps', 'Shoulder Tap Plank']::text[], 'strength', 'core', 'compound', 'static', 'beginner', array['Get in a high plank with hands under your shoulders and feet slightly wider than hip-width.', 'Tap one hand to the opposite shoulder while keeping your hips from rocking.', 'Return the hand and alternate sides at a steady pace.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Stability_Ball_Pike', 'Stability Ball Pike', array['Swiss Ball Pike', 'Exercise Ball Pike']::text[], 'strength', 'core', 'compound', 'pull', 'intermediate', array['Start in a plank with your shins or feet on a stability ball and hands on the floor under your shoulders.', 'Roll the ball in by lifting your hips toward the ceiling, keeping your legs straight.', 'Roll back out to a straight plank with control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Stability_Ball_Rollout', 'Stability Ball Rollout', array['Swiss Ball Rollout', 'Exercise Ball Rollout']::text[], 'strength', 'core', 'compound', 'pull', 'beginner', array['Kneel in front of a stability ball and rest your forearms on top of it.', 'Roll the ball forward by extending your arms and body in a straight line.', 'Pull the ball back in by squeezing your abs. Stop before your lower back sags.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Suitcase_Carry', 'Suitcase Carry', array['Single-Arm Farmer''s Walk', 'One-Arm Carry']::text[], 'strength', 'carry', 'compound', 'pull', 'beginner', array['Hold a heavy dumbbell or kettlebell in one hand at your side and stand tall.', 'Walk a set distance without leaning toward the weight, keeping your shoulders level.', 'Switch hands and repeat. Your side core works to keep you upright.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Suspension_Pike', 'Suspension Pike', array['TRX Pike', 'Ring Pike']::text[], 'strength', 'core', 'compound', 'pull', 'intermediate', array['Start in a plank with your feet in the straps or rings and hands on the floor.', 'Raise your hips toward the ceiling by folding at the hips, keeping your legs straight.', 'Lower back to a plank with control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Toes-to-Bar', 'Toes-to-Bar', array['Toes to Bar', 'T2B']::text[], 'strength', 'core', 'compound', 'pull', 'expert', array['Hang from a pull-up bar with a firm grip and a slight swing.', 'Pull your toes up to touch the bar by driving your legs up and curling your pelvis.', 'Lower under control and keep your swing small. Do knee raises first if this is too hard.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Windshield_Wipers', 'Windshield Wipers', array['Hanging Windshield Wipers']::text[], 'strength', 'core', 'compound', 'pull', 'expert', array['Hang from a pull-up bar and lift your legs straight up toward it.', 'Lower your legs to one side in a controlled arc, without letting your shoulders twist.', 'Bring them back up to the middle and over to the other side.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dead_Hang', 'Dead Hang', array['Bar Hang', 'Passive Hang']::text[], 'strength', 'isolation', 'isolation', 'static', 'beginner', array['Grip a pull-up bar with straight arms and let your feet leave the floor.', 'Hang with relaxed shoulders, or gently draw your shoulder blades down.', 'Hold as long as you can. Great for grip strength and loosening the shoulders.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Lateral_Walk', 'Band Lateral Walk', array['Banded Side Step', 'Lateral Band Walk']::text[], 'strength', 'isolation', 'isolation', 'static', 'beginner', array['Loop a band around your legs just above your knees or around your ankles, and stand in a quarter squat.', 'Step sideways, keeping tension in the band and your toes pointing forward.', 'Take a set number of steps one way, then return the other way.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Cable_Hip_Abduction', 'Cable Hip Abduction', array['Standing Cable Abduction', 'Cable Leg Abduction']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Attach an ankle strap to a low cable and strap it to the leg farthest from the stack.', 'Hold the machine for balance and lift your leg out to the side, keeping your torso upright.', 'Return slowly. Complete all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Clamshell', 'Clamshell', array['Clam Shell', 'Banded Clamshell']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Lie on your side with your knees bent and a band just above your knees.', 'Keep your feet together and lift your top knee as far as you can without rolling your hips back.', 'Lower slowly and repeat, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Copenhagen_Plank', 'Copenhagen Plank', array['Copenhagen Side Plank', 'Adductor Plank']::text[], 'strength', 'core', 'compound', 'static', 'expert', array['Lie on your side and place your top leg on a bench with your lower leg tucked under, and your forearm on the floor.', 'Lift your hips so your body is in a straight line, with your top leg doing the supporting.', 'Hold, then switch sides. Bend the top knee to make it easier.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Fire_Hydrant', 'Fire Hydrant', array['Fire Hydrants', 'Quadruped Hip Abduction']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Start on your hands and knees with your back flat.', 'Lift one knee out to the side, keeping the knee bent at 90 degrees, without rotating your torso.', 'Lower slowly and repeat all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Machine_Glute_Kickback', 'Machine Glute Kickback', array['Glute Kickback Machine', 'Standing Glute Kickback Machine']::text[], 'strength', 'isolation', 'isolation', 'push', 'beginner', array['Set up in the machine with your chest against the pad and the foot of one leg on the plate.', 'Push the plate back and up by squeezing your glute, keeping your torso steady.', 'Return slowly and repeat, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Side-Lying_Leg_Raise', 'Side-Lying Leg Raise', array['Side Leg Raise', 'Lateral Leg Raise']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Lie on your side with your body in a straight line and your head resting on your arm.', 'Raise your top leg straight up, keeping your toes pointing forward.', 'Lower slowly without letting your hips roll back, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Single-Leg_Hip_Thrust', 'Single-Leg Hip Thrust', array['Single-Leg Glute Bridge Thrust', 'One-Leg Hip Thrust']::text[], 'strength', 'hinge', 'compound', 'push', 'intermediate', array['Sit with your upper back against a bench, one foot on the floor and the other leg lifted.', 'Drive through your planted foot and lift your hips until your torso is level.', 'Squeeze your glute at the top, then lower with control. Do all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Smith_Machine_Hip_Thrust', 'Smith Machine Hip Thrust', array['Smith Hip Thrust']::text[], 'strength', 'hinge', 'compound', 'push', 'intermediate', array['Sit on the floor with your upper back against a bench and the Smith bar over your hips, padded if needed.', 'Drive through your heels and lift your hips until your thighs are parallel to the floor.', 'Squeeze your glutes at the top, then lower with control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Romanian_Deadlift', 'Band Romanian Deadlift', array['Banded RDL', 'Resistance Band RDL']::text[], 'strength', 'hinge', 'compound', 'pull', 'beginner', array['Stand on a band and hold the other end in both hands in front of your thighs.', 'Push your hips back with a flat back and soft knees until you feel a hamstring stretch.', 'Drive your hips forward to stand tall and squeeze your glutes.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Bodyweight_Bulgarian_Split_Squat', 'Bodyweight Bulgarian Split Squat', array['Bulgarian Split Squat Bodyweight', 'BW Bulgarian Split Squat']::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Stand about two feet in front of a bench and rest the top of one foot on it behind you.', 'Lower straight down until your front thigh is about parallel to the floor.', 'Drive through your front heel to stand, then switch legs after your reps.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Bodyweight_Lunge', 'Bodyweight Lunge', array['Walking Lunge Bodyweight', 'BW Lunge', 'Forward Lunge']::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Stand tall with your hands on your hips or clasped in front of you.', 'Step forward and lower your back knee toward the floor until both knees are bent about 90 degrees.', 'Push off your front foot back to the start, or step through into the next lunge.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Bodyweight_Split_Squat', 'Bodyweight Split Squat', array['Split Squat Bodyweight', 'BW Split Squat', 'Static Lunge']::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Stand in a long stance with one foot well forward of the other.', 'Lower your back knee toward the floor, keeping your torso upright.', 'Press through your front foot to rise, then switch legs after your reps.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Curtsy_Lunge', 'Curtsy Lunge', array['Curtsey Lunge', 'Cross-Behind Lunge']::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Stand tall with feet hip-width apart.', 'Step one foot back and across behind you, as if curtsying, and lower until your front thigh is about parallel.', 'Drive through your front foot to stand, then repeat on the other side.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Lateral_Lunge', 'Dumbbell Lateral Lunge', array['Dumbbell Side Lunge', 'DB Lateral Lunge', 'Goblet Lateral Lunge']::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Hold a dumbbell or kettlebell at your chest and stand with feet together.', 'Step wide to one side and sit your hips back, keeping the other leg straight and both feet flat.', 'Push through your bent leg to return to standing, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Leg_Curl', 'Dumbbell Leg Curl', array['DB Leg Curl', 'Dumbbell Hamstring Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'intermediate', array['Lie face down on a bench with a dumbbell held firmly between your feet.', 'Curl your heels toward your glutes, keeping your hips pressed down.', 'Lower slowly. Use a light weight; the dumbbell can slip.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Kettlebell_Deadlift', 'Kettlebell Deadlift', array['KB Deadlift']::text[], 'strength', 'hinge', 'compound', 'pull', 'beginner', array['Stand with feet hip-width apart and a kettlebell between your feet, hinging with a flat back to grab the handle.', 'Drive through your heels and stand tall, squeezing your glutes at the top.', 'Hinge back down and set the bell on the floor with control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Landmine_Squat', 'Landmine Squat', array['Landmine Goblet Squat']::text[], 'strength', 'squat', 'compound', 'push', 'beginner', array['Set a barbell in a landmine and hold the end at your chest with both hands, standing with feet shoulder-width apart.', 'Squat down with your chest up until your thighs are parallel to the floor or lower.', 'Drive back up to standing. The angle helps you stay upright.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Lateral_Lunge', 'Lateral Lunge', array['Side Lunge', 'Bodyweight Side Lunge', 'Cossack Lunge']::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Stand tall with feet together and your hands clasped in front.', 'Step wide to one side and sit your hips back, keeping the other leg straight and both feet flat.', 'Push through your bent leg to return to the start, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Lateral_Step-Up', 'Lateral Step-Up', array['Side Step-Up', 'Dumbbell Lateral Step-Up']::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Stand beside a box or bench with your near foot on top, holding dumbbells at your sides.', 'Drive through the top foot to step up until your leg is straight, keeping the other leg from pushing off.', 'Lower slowly to the floor. Complete all reps, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Pistol_Squat', 'Pistol Squat', array['Single-Leg Squat', 'One-Leg Squat']::text[], 'strength', 'lunge', 'compound', 'push', 'expert', array['Stand on one leg with the other leg held straight out in front of you.', 'Squat down on the standing leg, keeping your heel flat and your free leg off the floor.', 'Drive back up to standing. Hold on to a post or use a box for support while you build strength.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Reverse_Nordic', 'Reverse Nordic', array['Reverse Nordic Curl', 'Reverse Nordic Hamstring']::text[], 'strength', 'isolation', 'isolation', 'push', 'intermediate', array['Kneel on a pad with your body upright and your hips fully extended.', 'Lean back slowly as far as you can, keeping your hips forward and your body in one line.', 'Pull yourself back up to upright using your quads. Hold something sturdy if you need help.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Safety_Squat_Bar_Squat', 'Safety Squat Bar Squat', array['SSB Squat', 'Safety Bar Squat']::text[], 'strength', 'squat', 'compound', 'push', 'intermediate', array['Set the bar in the rack, duck under it, and rest the pad on your upper back with your hands on the handles.', 'Unrack, step back, and squat down until your thighs are at least parallel to the floor.', 'Drive back up to standing. The bar''s design keeps you more upright.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Single-Leg_Leg_Press', 'Single-Leg Leg Press', array['Single Leg Press', 'One-Leg Leg Press']::text[], 'strength', 'squat', 'compound', 'push', 'beginner', array['Sit in the leg press and place one foot in the middle of the platform with the other leg held off it.', 'Lower the platform until your knee is bent about 90 degrees.', 'Press back up without locking your knee, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Sissy_Squat', 'Sissy Squat', array['Sissy Squats']::text[], 'strength', 'squat', 'isolation', 'push', 'expert', array['Stand holding a post or rack for balance, raised on the balls of your feet.', 'Lean back and bend your knees forward, letting them travel far past your toes while your hips stay extended.', 'Lower as far as you can control, then rise back up. Go only as deep as your knees feel good.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Smith_Machine_Front_Squat', 'Smith Machine Front Squat', array['Smith Front Squat']::text[], 'strength', 'squat', 'compound', 'push', 'intermediate', array['Set the bar at shoulder height and rest it across the front of your shoulders with your feet slightly forward of the bar.', 'Unlock the bar and squat down with your chest up until your thighs are parallel to the floor.', 'Drive back up to standing and re-rack.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Suspension_Hamstring_Curl', 'Suspension Hamstring Curl', array['TRX Hamstring Curl', 'Ring Hamstring Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'intermediate', array['Lie on your back with your heels in the straps or rings and lift your hips into a bridge.', 'Curl your heels toward your glutes, keeping your hips high.', 'Extend your legs back out slowly without letting your hips drop.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Trap_Bar_Romanian_Deadlift', 'Trap Bar Romanian Deadlift', array['Hex Bar RDL', 'Trap Bar RDL']::text[], 'strength', 'hinge', 'compound', 'pull', 'intermediate', array['Stand inside a trap bar and hinge to grip the handles, with your back flat.', 'Stand up, then push your hips back and lower the bar down your thighs to just below your knees.', 'Drive your hips forward to stand tall.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Wall_Sit', 'Wall Sit', array['Wall Squat Hold', 'Isometric Wall Squat']::text[], 'strength', 'other', 'compound', 'static', 'beginner', array['Stand with your back against a wall and walk your feet out about two feet.', 'Slide down until your thighs are parallel to the floor, with your knees over your ankles.', 'Hold as long as you can, keeping your back flat against the wall.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Bird_Dog', 'Bird Dog', array['Bird-Dog', 'Quadruped Arm and Leg Raise']::text[], 'strength', 'other', 'compound', 'static', 'beginner', array['Start on your hands and knees with your back flat.', 'Reach one arm forward and the opposite leg back until both are level with your torso.', 'Hold briefly without letting your hips rotate, return, and switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('90_90_Hip_Switch', '90/90 Hip Switch', array['90 90 Hip Switch', '90/90 Hip Stretch', 'Hip 90/90']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Sit on the floor with both knees bent at 90 degrees and legs rotated to one side.', 'Rotate your knees across to the other side, keeping your feet on the floor.', 'Move back and forth with control, sitting tall. Stay in each position for a moment if you feel tightness.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Shoulder_Dislocates', 'Band Shoulder Dislocates', array['Shoulder Dislocates', 'Band Pass-Through']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Hold a light band wide in front of your thighs with straight arms.', 'Raise it overhead and then behind your back in a smooth arc, keeping your arms straight.', 'Return the same way. Use a wider grip if your shoulders feel pinched.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Cobra_Stretch', 'Cobra Stretch', array['Cobra Pose', 'Prone Press-Up']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Lie face down with your hands under your shoulders.', 'Press up gently, lifting your chest while keeping your hips on the floor.', 'Hold for a few breaths, feeling the stretch along your abs. Stop if you feel pain in your lower back.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Couch_Stretch', 'Couch Stretch', array['Quad and Hip Flexor Stretch', 'Wall Quad Stretch']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Kneel with one shin up against a wall or couch behind you and the other foot planted in front.', 'Squeeze your glute and push your hips forward, keeping your torso upright.', 'Hold, then switch legs. Move your knee further from the wall to make it easier.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Downward_Dog', 'Downward Dog', array['Downward-Facing Dog', 'Down Dog']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Start on your hands and knees, then lift your hips up and back into an upside-down V.', 'Press your hands into the floor and push your chest toward your thighs.', 'Pedal your heels toward the floor and hold, breathing slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Open_Book_Stretch', 'Open Book Stretch', array['Open Book', 'Thoracic Rotation Stretch']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Lie on your side with your knees bent at 90 degrees and arms stretched out in front, palms together.', 'Lift your top arm and rotate it open toward the other side, following your hand with your eyes.', 'Return slowly. Complete all reps, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Pigeon_Pose', 'Pigeon Pose', array['Pigeon Stretch', 'Figure Four Floor Stretch']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['From a plank or hands and knees, bring one knee forward behind your wrist with your shin angled across.', 'Slide the other leg straight back and lower your hips toward the floor.', 'Hold, folding forward for a deeper stretch, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Thread_the_Needle', 'Thread the Needle', array['Thread the Needle Stretch']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Start on your hands and knees.', 'Slide one arm under your body along the floor, palm up, and lower your shoulder and head to the floor.', 'Hold, then unwind and switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Wall_Slide', 'Wall Slide', array['Wall Angel', 'Wall Slides']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Stand with your back, head, and arms against a wall, elbows bent at 90 degrees.', 'Slide your arms up overhead while keeping your forearms and lower back against the wall.', 'Slide back down slowly. Stop where you can no longer keep contact.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Hang_Power_Clean', 'Hang Power Clean', array['Power Clean From Hang']::text[], 'strength', 'hinge', 'compound', 'pull', 'intermediate', array['Hold a barbell at mid-thigh with your hips hinged, back flat, and shoulders over the bar.', 'Explosively extend your hips and knees, shrug, and pull yourself under the bar.', 'Catch the bar on your shoulders in a quarter squat, stand tall, and lower it back to your thighs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Face_Pull', 'Band Face Pull', array['Resistance Band Face Pull']::text[], 'strength', 'other', 'compound', 'pull', 'beginner', array['Anchor a band at about face height and step back until there is tension, holding the ends with both hands.', 'Pull the band to your face, pulling your hands apart and your elbows high.', 'Squeeze your shoulder blades, then return with control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Barbell_Z_Press', 'Barbell Z Press', array['Z Press']::text[], 'strength', 'other', 'compound', 'push', 'expert', array['Sit on the floor with your legs straight in front of you and the bar racked at shoulder height, or cleaned to your shoulders.', 'Brace your core and press the bar straight overhead, keeping your torso upright.', 'Lower to your shoulders under control. Start light; there is no leg drive to help.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Bent-Over_Dumbbell_Reverse_Fly', 'Bent-Over Dumbbell Reverse Fly', array['Bent-Over Rear Delt Fly', 'Dumbbell Rear Delt Fly']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Hold dumbbells and hinge at the hips until your torso is nearly parallel to the floor, with arms hanging down.', 'Raise your arms out to the sides with a slight bend in the elbows until they reach shoulder height.', 'Lower slowly. Keep your neck neutral and avoid swinging.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Cable_Y-Raise', 'Cable Y-Raise', array['Cable Y Raise']::text[], 'strength', 'isolation', 'isolation', 'pull', 'intermediate', array['Set the cables low and hold the handles crossed in front of you, standing tall.', 'Raise both arms up and out in a Y shape until they are overhead, with thumbs pointing back.', 'Lower slowly and keep your ribs down.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Half-Kneeling_Landmine_Press', 'Half-Kneeling Landmine Press', array['Half Kneeling Landmine Press', 'Kneeling Landmine Press']::text[], 'strength', 'other', 'compound', 'push', 'intermediate', array['Set a barbell in a landmine and kneel on the knee opposite your pressing arm, with the other foot forward.', 'Hold the end of the bar at your shoulder and press it up and forward until your arm is straight.', 'Lower under control, keeping your torso tall. Do all reps, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Lean-Away_Dumbbell_Lateral_Raise', 'Lean-Away Dumbbell Lateral Raise', array['Lean Away Lateral Raise', 'Leaning Lateral Raise']::text[], 'strength', 'isolation', 'isolation', 'pull', 'intermediate', array['Hold a dumbbell in one hand and a sturdy post with the other, leaning your body away at an angle.', 'Raise the dumbbell out to the side to shoulder height, keeping a slight bend in your elbow.', 'Lower slowly. The lean keeps tension on your side delts at the bottom.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Trap_Bar_Shrug', 'Trap Bar Shrug', array['Hex Bar Shrug']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Stand inside a trap bar and pick it up with your arms straight at your sides.', 'Shrug your shoulders straight up toward your ears without bending your elbows.', 'Hold briefly, then lower slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Tricep_Pushdown', 'Band Tricep Pushdown', array['Resistance Band Pushdown', 'Band Pushdown']::text[], 'strength', 'isolation', 'isolation', 'push', 'beginner', array['Anchor a band overhead, hold the ends with elbows at your sides, and bend your elbows to start.', 'Push your hands down until your arms are fully straight.', 'Return slowly, keeping your elbows pinned to your sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Cable_Tricep_Kickback', 'Cable Tricep Kickback', array['Cable Kickback', 'Cable Triceps Kickback']::text[], 'strength', 'isolation', 'isolation', 'push', 'beginner', array['Set a cable low, hinge forward, and hold the handle with your upper arm tucked tight against your side.', 'Extend your elbow until your arm is straight behind you.', 'Return slowly without moving your upper arm. Do all reps, then switch sides.']::text[], '{}'::text[], true, true, 'catalog')
